#!/usr/bin/env bash
# Check task 03: ceilings come from the file, the generated file is frozen, and
# the behaviour survives a different limit file.
set -euo pipefail

here=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
repo=${1:-$PWD}
[[ -d "$repo" ]] || { echo "no such work dir: $repo" >&2; exit 1; }
repo=$(cd -- "$repo" && pwd)

fail() {
  echo "FAIL: $*" >&2
  exit 1
}

cmp -s -- "$here/fixture/config/limits.json" "$repo/config/limits.json" \
  || fail "config/limits.json changed; the file is generated by ops"

if ! (cd -- "$repo" && PYTHONDONTWRITEBYTECODE=1 python3 -m unittest discover -s tests -q); then
  fail "the test suite failed"
fi

there=$(mktemp -d "$repo/.zc-eval.XXXXXX")
trap 'rm -rf -- "${there:?}"' EXIT

cat > "$there/limits.json" <<'JSON'
{"burst": 250, "requests": 40}
JSON

if ! (cd -- "$repo" && PYTHONDONTWRITEBYTECODE=1 LIMITS_PATH="$there/limits.json" python3 - <<'PY'
from app.limits import clamp

assert clamp(100, "requests") == 40, clamp(100, "requests")
assert clamp(999, "burst") == 250, clamp(999, "burst")
assert clamp(10, "requests") == 10
assert clamp(10, "unknown-key") == 10
assert clamp(500, "unknown-key") == 40
print("limit behaviour ok")
PY
); then
  fail "clamp ignores the configured limit file"
fi

echo "task 03 check passed"
